INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-moon-distance', 'Earth–Moon distance', 384400, 'km', 'NASA gives the Moon''s average distance as 384,400 km. The orbit is slightly oval, so the distance changes through the month.', 'https://science.nasa.gov/moon/facts/', 'NASA Science', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0, 'NASA mean distance');
