INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-jupiter-diameter', 'Jupiter', 142984, 'km', 'Jupiter''s equatorial diameter is about 142,984 km, more than eleven Earths across.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/jupiterfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0, 'NASA fact sheet');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-mercury-distance', 'Mercury', 57909000, 'km', 'Mercury orbits at a semimajor axis of about 57.9 million km.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/mercuryfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0, 'NASA fact sheet');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-venus-distance', 'Venus', 108210000, 'km', 'Venus orbits at a semimajor axis of about 108.2 million km.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/venusfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0, 'NASA fact sheet');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-earth-distance', 'Earth', 149598000, 'km', 'One astronomical unit, Earth''s average distance from the Sun, is about 149.6 million km.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0, 'NASA fact sheet');
