INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-mars-diameter', 'Mars', 6792.4, 'km', 'Mars''s equatorial diameter is about 6,792 km.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0, 'NASA fact sheet');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-earth-year', 'Earth', 365.256, 'days', 'Earth''s sidereal orbit period is about 365.256 days.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 1, 0, 'NASA fact sheet');
