INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-whale-mass', 'Blue whale', 150000, 'kg', 'A large blue whale weighs on the order of 150 tonnes, far beyond any land animal alive today.', 'https://www.fisheries.noaa.gov/species/blue-whale', 'NOAA Fisheries', '2026-11-21', 'Public domain (U.S. government work)', 'nature', 2, 0, 'Order-of-magnitude adult');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-mouse-mass', 'House mouse', 0.02, 'kg', 'An adult house mouse weighs about 20 grams.', 'https://en.wikipedia.org/wiki/House_mouse', 'Wikipedia: House mouse', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, 'Typical adult');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-penguin-mass', 'Emperor penguin', 30, 'kg', 'An adult emperor penguin is around 30 kg. Weight swings a lot across the breeding season.', 'https://www.antarctica.gov.au/about-antarctica/animals/penguins/emperor-penguins/', 'Australian Antarctic Program', '2026-11-21', 'Australian Antarctic Program', 'nature', 2, 0, 'Typical adult');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-bear-mass', 'Polar bear', 450, 'kg', 'Adult male polar bears are often around 350 to 700 kg. 450 kg is a mid-range figure, not a record.', 'https://en.wikipedia.org/wiki/Polar_bear', 'Wikipedia: Polar bear', '2026-11-21', 'CC BY-SA 4.0', 'nature', 2, 0, 'Mid-range adult male');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-hippo-mass', 'Hippopotamus', 1500, 'kg', 'A large male hippopotamus is around 1,500 kg. Adults vary, and the order against a polar bear does not.', 'https://en.wikipedia.org/wiki/Hippopotamus', 'Wikipedia: Hippopotamus', '2026-11-21', 'CC BY-SA 4.0', 'nature', 2, 0, 'Typical large male');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-albatross', 'Wingspan of a wandering albatross', 3.5, 'm', 'The wandering albatross has the largest wingspan of any living bird, up to about 3.5 m.', 'https://www.britannica.com/animal/wandering-albatross', 'Britannica: wandering albatross', '2026-11-21', 'Encyclopaedia Britannica (sample citation)', 'nature', 2, 0, 'Approximate maximum');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-elephant-gestation', 'African elephant', 660, 'days', 'African elephant pregnancies last about 22 months, close to 660 days, the longest of any land mammal.', 'https://en.wikipedia.org/wiki/African_bush_elephant', 'Wikipedia: African bush elephant', '2026-11-21', 'CC BY-SA 4.0', 'nature', 2, 0, 'Approximate mean');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-human-gestation', 'Human', 280, 'days', 'A typical human pregnancy is counted as about 40 weeks, or 280 days, from the last menstrual period.', 'https://www.nichd.nih.gov/health/topics/pregnancy/conditioninfo', 'NICHD', '2026-11-21', 'Public domain (U.S. government work)', 'human-body', 1, 0, 'Clinical average');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-un-members', 'United Nations member states', 193, 'member states', 'The United Nations has 193 member states, unchanged since South Sudan joined in 2011.', 'https://www.un.org/en/about-us/member-states', 'United Nations', '2026-11-21', 'United Nations public information', 'geography', 1, 0, 'Membership since 2011');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-canada-area', 'Canada', 9984670, 'km²', 'The Factbook lists Canada''s total area, including inland water, as 9,984,670 km².', 'https://www.cia.gov/the-world-factbook/countries/canada/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, 'CIA World Factbook');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-china-area', 'China', 9596960, 'km²', 'The Factbook lists China''s total area as 9,596,960 km².', 'https://www.cia.gov/the-world-factbook/countries/china/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, 'CIA World Factbook');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-vatican-area', 'Vatican City', 0.44, 'km²', 'Vatican City covers about 0.44 km², the smallest country by area.', 'https://www.cia.gov/the-world-factbook/countries/holy-see/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 1, 0, 'CIA World Factbook');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-japan-area', 'Japan', 377915, 'km²', 'The Factbook lists Japan''s total area as about 377,915 km².', 'https://www.cia.gov/the-world-factbook/countries/japan/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, 'CIA World Factbook');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-mexico-area', 'Mexico', 1964375, 'km²', 'The Factbook lists Mexico''s total area as 1,964,375 km².', 'https://www.cia.gov/the-world-factbook/countries/mexico/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, 'CIA World Factbook');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-brazil-area', 'Brazil', 8515770, 'km²', 'The Factbook lists Brazil''s total area as 8,515,770 km².', 'https://www.cia.gov/the-world-factbook/countries/brazil/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, 'CIA World Factbook');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-russia-area', 'Total area of Russia', 17098242, 'km²', 'Russia is the largest country by area, 17,098,242 km² in the Factbook, including inland water.', 'https://www.cia.gov/the-world-factbook/countries/russia/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, 'CIA World Factbook');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-australia-area', 'Australia', 7741220, 'km²', 'The Factbook lists Australia''s total area as 7,741,220 km².', 'https://www.cia.gov/the-world-factbook/countries/australia/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, 'CIA World Factbook');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-india-area', 'India', 3287263, 'km²', 'The Factbook lists India''s total area as 3,287,263 km².', 'https://www.cia.gov/the-world-factbook/countries/india/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, 'CIA World Factbook');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-c14', 'Half-life of carbon-14', 5730, 'years', 'NIST describes carbon-14''s half-life as about 5,730 years. Some radiocarbon calculations still use the older Libby value of 5,568.', 'https://www.nist.gov/how-do-you-measure-it/how-do-you-know-age-fossils-and-other-old-things', 'NIST', '2026-11-21', 'Public domain (U.S. government work)', 'science', 2, 0, 'Commonly cited half-life');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-sound', 'Speed of sound in dry air at 20 °C', 343, 'm/s', 'In dry air at 20 °C, sound travels at about 343 m/s. Warmer air is faster.', 'https://en.wikipedia.org/wiki/Speed_of_sound', 'Wikipedia: Speed of sound', '2026-11-21', 'CC BY-SA 4.0', 'science', 2, 0, '20 °C, dry air');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-tin-melt', 'Tin', 231.93, '°C', 'Tin melts at about 232 °C at ordinary pressure.', 'https://www.rsc.org/periodic-table/element/50/tin', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, 'Standard pressure');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-gold-melt', 'Gold', 1064.18, '°C', 'Gold melts at about 1,064 °C.', 'https://www.rsc.org/periodic-table/element/79/gold', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, 'Standard pressure');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-iron-melt', 'Iron', 1538, '°C', 'Iron melts at about 1,538 °C.', 'https://www.rsc.org/periodic-table/element/26/iron', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, 'Standard pressure');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-tungsten-melt', 'Tungsten', 3422, '°C', 'Tungsten has the highest melting point of any metal, about 3,422 °C.', 'https://www.rsc.org/periodic-table/element/74/tungsten', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 3, 0, 'Standard pressure');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-aluminum-melt', 'Aluminium', 660.32, '°C', 'Aluminium melts at about 660 °C.', 'https://www.rsc.org/periodic-table/element/13/aluminium', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, 'Standard pressure');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-copper-melt', 'Copper', 1084.62, '°C', 'Copper melts at about 1,085 °C.', 'https://www.rsc.org/periodic-table/element/29/copper', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, 'Standard pressure');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-gold-z', 'Gold', 79, 'protons', 'Gold is element 79.', 'https://www.rsc.org/periodic-table/element/79/gold', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, 'Exact');
