INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-marathon', 'Length of a standard marathon', 42.195, 'km', 'The marathon is standardized at 42.195 km, the distance fixed after the 1908 London course.', 'https://worldathletics.org/disciplines/road-running/marathon', 'World Athletics', '2026-11-21', 'World Athletics competition rules', 'culture', 1, 0, 'Current standard');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-beethoven', 'Beethoven''s Ninth', 1824, 'year', 'Beethoven''s Ninth Symphony was first performed in Vienna on 7 May 1824.', 'https://en.wikipedia.org/wiki/Symphony_No._9_(Beethoven)', 'Wikipedia: Symphony No. 9 (Beethoven)', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '7 May 1824');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-rite', 'The Rite of Spring', 1913, 'year', 'Stravinsky''s The Rite of Spring premiered in Paris on 29 May 1913.', 'https://en.wikipedia.org/wiki/The_Rite_of_Spring', 'Wikipedia: The Rite of Spring', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '29 May 1913');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-figaro', 'The Marriage of Figaro', 1786, 'year', 'Mozart''s The Marriage of Figaro opened in Vienna on 1 May 1786.', 'https://en.wikipedia.org/wiki/The_Marriage_of_Figaro', 'Wikipedia: The Marriage of Figaro', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '1 May 1786');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-messiaen', 'Quartet for the End of Time', 1941, 'year', 'Messiaen''s Quartet for the End of Time was first played in a prisoner-of-war camp on 15 January 1941.', 'https://en.wikipedia.org/wiki/Quatuor_pour_la_fin_du_temps', 'Wikipedia: Quatuor pour la fin du temps', '2026-11-21', 'CC BY-SA 4.0', 'culture', 3, 0, '15 January 1941');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-mona', 'Mona Lisa', 0.4081, 'm²', 'The Mona Lisa''s panel is 77 cm by 53 cm, about 0.41 square metres.', 'https://collections.louvre.fr/en/ark:/53355/cl010062370', 'Louvre', '2026-11-21', 'Louvre collection record', 'culture', 2, 0, 'Louvre dimensions');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-guernica', 'Guernica', 27.1266, 'm²', 'Guernica measures 349.3 cm by 776.6 cm, about 27 square metres.', 'https://www.museoreinasofia.es/en/collections/artwork/guernica', 'Museo Reina Sofía', '2026-11-21', 'Museo Reina Sofía collection record', 'culture', 2, 0, 'Museum dimensions');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-shakespeare', 'Year of Shakespeare''s birth', 1564, 'year', 'Shakespeare was baptised on 26 April 1564. The exact birth date was not written down; the year was.', 'https://en.wikipedia.org/wiki/William_Shakespeare', 'Wikipedia: William Shakespeare', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, 'Baptismal year 1564');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-principia', 'Newton''s Principia', 1687, 'year', 'Newton''s Principia was published in 1687.', 'https://en.wikipedia.org/wiki/Philosophi%C3%A6_Naturalis_Principia_Mathematica', 'Wikipedia: Philosophiæ Naturalis Principia Mathematica', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '1687');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-origin', 'On the Origin of Species', 1859, 'year', 'Darwin''s On the Origin of Species was published in 1859.', 'https://en.wikipedia.org/wiki/On_the_Origin_of_Species', 'Wikipedia: On the Origin of Species', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '1859');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-equator', 'Equatorial circumference of Earth', 40075.017, 'km', 'NASA lists Earth''s equatorial circumference as 40,075.017 km. The polar circumference is a little shorter.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, 'NASA fact sheet');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage) VALUES ('f-elements', 'Confirmed chemical elements', 118, 'elements', 'IUPAC''s periodic table lists 118 confirmed elements. The newest names were adopted in 2016.', 'https://iupac.org/what-we-do/periodic-table-of-elements/', 'IUPAC', '2026-11-21', 'IUPAC', 'science', 1, 0, 'Current IUPAC table');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-space-moon', 'How far is the Moon from Earth, on average?', 'estimate', 'km', 'higher', 'distance-km', '["f-moon-distance"]', '["f-moon-distance"]', 'NASA gives the Moon''s average distance as 384,400 km. The orbit is slightly oval, so the real distance swings by tens of thousands of kilometres.', 'https://science.nasa.gov/moon/facts/', 'NASA Science', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-space-giants', 'Which planet has the larger equatorial diameter?', 'compare', NULL, 'higher', NULL, '["f-earth-diameter","f-jupiter-diameter"]', '["f-earth-diameter","f-jupiter-diameter"]', 'Jupiter''s equatorial diameter is about 142,984 km, more than eleven times Earth''s 12,756 km.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/jupiterfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-space-orbits', 'Order these planets from closest to the Sun to farthest.', 'rank', NULL, 'lower', NULL, '["f-mercury-distance","f-venus-distance","f-earth-distance","f-mars-distance"]', '["f-earth-distance","f-mercury-distance","f-mars-distance","f-venus-distance"]', 'Average distances from the Sun run Mercury, Venus, Earth, then Mars: about 58 million km out to about 228 million km.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-space-light', 'What is the speed of light in a vacuum?', 'estimate', 'm/s', 'higher', 'speed-ms', '["f-light-speed"]', '["f-light-speed"]', 'Since 1983 the metre has been defined from this speed. In a vacuum, light travels at exactly 299,792,458 metres per second.', 'https://physics.nist.gov/cgi-bin/cuu/Value?c', 'NIST', '2026-11-21', 'Public domain (U.S. government work)', 'science', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-space-year', 'Which planet takes longer to orbit the Sun?', 'compare', NULL, 'higher', NULL, '["f-earth-year","f-mars-year"]', '["f-earth-year","f-mars-year"]', 'A Martian year lasts about 687 Earth days. Earth''s sidereal year is about 365.256 days.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-earth-everest', 'How high is Mount Everest above sea level?', 'estimate', 'm', 'higher', 'length-m', '["f-everest"]', '["f-everest"]', 'In 2020 Nepal and China jointly announced a height of 8,848.86 m, including the snow cap.', 'https://dos.gov.np/everest/index.html', 'Survey Department, Government of Nepal', '2026-11-21', 'Government of Nepal survey publication', 'geography', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-earth-seas', 'Which sea has the larger surface area?', 'compare', NULL, 'higher', NULL, '["f-mediterranean","f-caribbean"]', '["f-mediterranean","f-caribbean"]', 'Standard reference areas put the Caribbean at about 2.75 million km² and the Mediterranean at about 2.5 million km². Boundaries of seas are conventional, so both figures are rounded.', 'https://en.wikipedia.org/wiki/Caribbean_Sea', 'Wikipedia: Caribbean Sea', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-earth-oceans', 'Order these oceans by surface area, largest first.', 'rank', NULL, 'higher', NULL, '["f-pacific","f-atlantic","f-indian","f-arctic"]', '["f-arctic","f-indian","f-pacific","f-atlantic"]', 'Counting the Southern Ocean separately, the Pacific is still by far the largest of these four, and the Arctic is the smallest. Figures follow a NOAA compilation widely reprinted from the ocean article on Wikipedia.', 'https://en.wikipedia.org/wiki/Ocean', 'Wikipedia: Ocean, citing NOAA', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-earth-trench', 'How deep is Challenger Deep, the deepest known point in the ocean?', 'estimate', 'm', 'higher', 'length-m', '["f-challenger"]', '["f-challenger"]', 'A 2020 crewed survey, reported by NOAA, put the deepest observed seafloor in Challenger Deep at 10,935 metres, give or take about 6 metres.', 'https://oceanexplorer.noaa.gov/ocean-fact/ocean-depth/', 'NOAA Ocean Exploration', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 3, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-earth-peaks', 'Which peak is higher above sea level?', 'compare', NULL, 'higher', NULL, '["f-kilimanjaro","f-denali"]', '["f-kilimanjaro","f-denali"]', 'Denali''s official USGS elevation is 6,190 m. Kilimanjaro''s Uhuru Peak is 5,895 m. Everest is higher than both, but that is a different question.', 'https://www.usgs.gov/news/national-news-release/new-elevation-nations-highest-peak', 'U.S. Geological Survey', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-body-bones', 'How many bones are in a typical adult human skeleton?', 'estimate', 'bones', 'higher', 'count', '["f-bones-adult"]', '["f-bones-adult"]', 'Anatomy texts settle on 206 bones in a typical adult. The count can vary slightly with small sesamoid bones, and babies start with more that later fuse.', 'https://en.wikipedia.org/wiki/Human_skeleton', 'Wikipedia: Human skeleton', '2026-11-21', 'CC BY-SA 4.0', 'human-body', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-body-lungs', 'Which lung has more lobes?', 'compare', NULL, 'higher', NULL, '["f-right-lung","f-left-lung"]', '["f-left-lung","f-right-lung"]', 'The right lung has three lobes. The left has two, which leaves room for the heart.', 'https://www.ncbi.nlm.nih.gov/books/NBK470197/', 'NCBI StatPearls: Anatomy, Thorax, Lungs', '2026-11-21', 'NCBI Bookshelf', 'human-body', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-body-counts', 'Order these by how many a typical person has, fewest first.', 'rank', NULL, 'lower', NULL, '["f-baby-teeth","f-teeth","f-chromosomes"]', '["f-chromosomes","f-baby-teeth","f-teeth"]', 'Children have 20 baby teeth. A full adult set, including wisdom teeth, is 32. Most human cells carry 46 chromosomes.', 'https://www.genome.gov/about-genomics/fact-sheets/Chromosomes-Fact-Sheet', 'National Human Genome Research Institute', '2026-11-21', 'Public domain (U.S. government work)', 'human-body', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-body-neurons', 'About how many neurons are in an adult human brain?', 'estimate', 'neurons', 'higher', 'count', '["f-neurons"]', '["f-neurons"]', 'A 2009 count by Azevedo and colleagues estimated about 86 billion neurons in the adult male human brain, with a margin of a few billion.', 'https://pubmed.ncbi.nlm.nih.gov/19226510/', 'PubMed: Azevedo et al. 2009', '2026-11-21', 'Public research abstract', 'human-body', 3, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-body-gut', 'Which is longer in a typical adult?', 'compare', NULL, 'higher', NULL, '["f-small-intestine","f-large-intestine"]', '["f-small-intestine","f-large-intestine"]', 'References put the small intestine at about 6 metres and the large intestine at about 1.5 metres. Both lengths vary from person to person.', 'https://en.wikipedia.org/wiki/Small_intestine', 'Wikipedia: Small intestine', '2026-11-21', 'CC BY-SA 4.0', 'human-body', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-inv-order', 'Order these from earliest to latest.', 'rank', NULL, 'lower', NULL, '["f-clock","f-gutenberg","f-telescope","f-telephone"]', '["f-telephone","f-clock","f-telescope","f-gutenberg"]', 'The earliest recorded European mechanical clock is dated to 1283. Gutenberg''s metal type is traditionally placed around 1440, the telescope patent in 1608, and Bell''s telephone patent in 1876.', 'https://en.wikipedia.org/wiki/Clock', 'Wikipedia: Clock', '2026-11-21', 'CC BY-SA 4.0', 'inventions', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-inv-piano', 'How many keys does a standard modern piano have?', 'estimate', 'keys', 'higher', 'count', '["f-piano"]', '["f-piano"]', 'The modern piano keyboard settled on 88 keys, from A0 to C8.', 'https://en.wikipedia.org/wiki/Musical_keyboard', 'Wikipedia: Musical keyboard', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-inv-towers', 'Which tower is taller, to the tip?', 'compare', NULL, 'higher', NULL, '["f-eiffel","f-cn-tower"]', '["f-eiffel","f-cn-tower"]', 'The CN Tower in Toronto is 553.3 m. The Eiffel Tower, antennas included, is 330 m.', 'https://en.wikipedia.org/wiki/CN_Tower', 'Wikipedia: CN Tower', '2026-11-21', 'CC BY-SA 4.0', 'inventions', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-inv-empire', 'How tall is the Empire State Building, to the tip of its antenna?', 'estimate', 'm', 'higher', 'length-m', '["f-empire"]', '["f-empire"]', 'The building''s own fact sheet gives 1,454 feet to the tip, about 443.2 metres.', 'https://www.esbnyc.com/about/facts-figures', 'Empire State Building', '2026-11-21', 'Official building fact sheet', 'inventions', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-inv-first', 'Which came first?', 'compare', NULL, 'lower', NULL, '["f-railway","f-wright"]', '["f-wright","f-railway"]', 'The Stockton and Darlington Railway opened in 1825. The Wright Flyer flew at Kitty Hawk in 1903.', 'https://airandspace.si.edu/collection-objects/1903-wright-flyer/nasm_A19610048000', 'Smithsonian National Air and Space Museum', '2026-11-21', 'Public domain (U.S. government work)', 'inventions', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-land-pyramid', 'What was the original height of the Great Pyramid of Giza?', 'estimate', 'm', 'higher', 'length-m', '["f-pyramid-height"]', '["f-pyramid-height"]', 'The Great Pyramid originally rose about 146.6 m. The outer casing is gone, so it stands a little lower today.', 'https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza', 'Wikipedia: Great Pyramid of Giza', '2026-11-21', 'CC BY-SA 4.0', 'history', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-land-older', 'Which document is older?', 'compare', NULL, 'lower', NULL, '["f-magna","f-declaration"]', '["f-declaration","f-magna"]', 'Magna Carta was sealed in 1215. The Declaration of Independence was adopted in 1776.', 'https://en.wikipedia.org/wiki/Magna_Carta', 'Wikipedia: Magna Carta', '2026-11-21', 'CC BY-SA 4.0', 'history', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-land-timeline', 'Order these from oldest to newest.', 'rank', NULL, 'lower', NULL, '["f-pyramid-year","f-parthenon","f-colosseum","f-taj"]', '["f-taj","f-colosseum","f-pyramid-year","f-parthenon"]', 'Conventional completion dates: the Great Pyramid around 2560 BCE, the Parthenon in 438 BCE, the Colosseum in 80 CE, and the Taj Mahal complex in 1653. The pyramid''s exact year is debated; the order is not.', 'https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza', 'Wikipedia: Great Pyramid of Giza', '2026-11-21', 'CC BY-SA 4.0', 'history', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-land-liberty', 'How tall is the Statue of Liberty from the ground to the tip of the torch?', 'estimate', 'm', 'higher', 'length-m', '["f-liberty-total"]', '["f-liberty-total"]', 'The National Park Service lists the height from the ground to the tip of the torch as 92.99 metres. The figure of Liberty herself is 46 metres; the rest is the pedestal.', 'https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm', 'U.S. National Park Service', '2026-11-21', 'Public domain (U.S. government work)', 'culture', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-land-statues', 'Which statue is taller, not counting its pedestal?', 'compare', NULL, 'higher', NULL, '["f-liberty-figure","f-christ-statue"]', '["f-christ-statue","f-liberty-figure"]', 'Liberty''s figure, from heel to torch, is 46.05 m. Christ the Redeemer''s statue is 30 m, with a separate pedestal of about 8 m.', 'https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm', 'U.S. National Park Service', '2026-11-21', 'Public domain (U.S. government work)', 'culture', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-nat-whale', 'About how long can the largest blue whales grow?', 'estimate', 'm', 'higher', 'length-m', '["f-whale-length"]', '["f-whale-length"]', 'NOAA describes the largest blue whales as reaching about 30 metres. Most individuals are shorter. They are the largest animals known to have lived.', 'https://www.fisheries.noaa.gov/species/blue-whale', 'NOAA Fisheries', '2026-11-21', 'Public domain (U.S. government work)', 'nature', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-nat-heavy', 'Which is heavier?', 'compare', NULL, 'higher', NULL, '["f-whale-mass","f-elephant-mass"]', '["f-elephant-mass","f-whale-mass"]', 'A large blue whale weighs on the order of 150 tonnes. A large male African savanna elephant is about 6 tonnes.', 'https://www.fisheries.noaa.gov/species/blue-whale', 'NOAA Fisheries', '2026-11-21', 'Public domain (U.S. government work)', 'nature', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-nat-masses', 'Order these by typical adult body mass, lightest first.', 'rank', NULL, 'lower', NULL, '["f-mouse-mass","f-penguin-mass","f-bear-mass","f-hippo-mass"]', '["f-bear-mass","f-mouse-mass","f-hippo-mass","f-penguin-mass"]', 'Typical masses, not records: a house mouse around 20 grams, an emperor penguin around 30 kg, a male polar bear around 450 kg, and a large male hippo around 1,500 kg. Individuals vary, and the order does not.', 'https://en.wikipedia.org/wiki/Hippopotamus', 'Wikipedia: Hippopotamus', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-nat-wings', 'What is the wingspan of the largest wandering albatrosses?', 'estimate', 'm', 'higher', 'length-m', '["f-albatross"]', '["f-albatross"]', 'The wandering albatross has the largest wingspan of any living bird, up to about 3.5 metres. It spends most of its life gliding over the Southern Ocean.', 'https://www.britannica.com/animal/wandering-albatross', 'Britannica: wandering albatross', '2026-11-21', 'Encyclopaedia Britannica (sample citation)', 'nature', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-nat-gestation', 'Which pregnancy lasts longer?', 'compare', NULL, 'higher', NULL, '["f-elephant-gestation","f-human-gestation"]', '["f-human-gestation","f-elephant-gestation"]', 'African elephant pregnancies last about 22 months, near 660 days. A typical human pregnancy is counted as about 280 days.', 'https://en.wikipedia.org/wiki/African_bush_elephant', 'Wikipedia: African bush elephant', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-geo-un', 'How many member states does the United Nations have?', 'estimate', 'member states', 'higher', 'count', '["f-un-members"]', '["f-un-members"]', 'The United Nations has 193 member states. That count has been stable since South Sudan joined in 2011. The Holy See and Palestine are observer states, not members.', 'https://www.un.org/en/about-us/member-states', 'United Nations', '2026-11-21', 'United Nations public information', 'geography', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-geo-canada', 'Which country has the larger total area, including inland water?', 'compare', NULL, 'higher', NULL, '["f-canada-area","f-china-area"]', '["f-china-area","f-canada-area"]', 'The CIA World Factbook lists Canada at 9,984,670 km² and China at 9,596,960 km². Inland water is included, which is why this is not a land-only ranking.', 'https://www.cia.gov/the-world-factbook/countries/canada/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-geo-areas', 'Order these by total area, smallest first.', 'rank', NULL, 'lower', NULL, '["f-vatican-area","f-japan-area","f-mexico-area","f-brazil-area"]', '["f-brazil-area","f-vatican-area","f-mexico-area","f-japan-area"]', 'Vatican City is under half a square kilometre. Japan is about 378,000 km², Mexico about 2.0 million, and Brazil about 8.5 million.', 'https://www.cia.gov/the-world-factbook/countries/brazil/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-geo-russia', 'What is the total area of Russia, including inland water?', 'estimate', 'km²', 'higher', 'area-km2', '["f-russia-area"]', '["f-russia-area"]', 'The CIA World Factbook gives Russia a total area of 17,098,242 km². It is the largest country on Earth by area.', 'https://www.cia.gov/the-world-factbook/countries/russia/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-geo-brazil', 'Which country has the larger total area?', 'compare', NULL, 'higher', NULL, '["f-india-area","f-australia-area"]', '["f-india-area","f-australia-area"]', 'In the CIA World Factbook, Australia is 7,741,220 km² and India is 3,287,263 km².', 'https://www.cia.gov/the-world-factbook/countries/australia/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-sci-c14', 'What is the half-life of carbon-14, in years?', 'estimate', 'years', 'higher', 'years', '["f-c14"]', '["f-c14"]', 'NIST describes carbon-14''s half-life as about 5,730 years. Radiocarbon labs still use an older conventional Libby value of 5,568 years for some calculations. This question uses 5,730.', 'https://www.nist.gov/how-do-you-measure-it/how-do-you-know-age-fossils-and-other-old-things', 'NIST', '2026-11-21', 'Public domain (U.S. government work)', 'science', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-sci-melt', 'Which metal has the higher melting point?', 'compare', NULL, 'higher', NULL, '["f-aluminum-melt","f-copper-melt"]', '["f-aluminum-melt","f-copper-melt"]', 'Copper melts at about 1,085 °C. Aluminium melts at about 660 °C. Both are the ordinary-pressure values from the Royal Society of Chemistry.', 'https://www.rsc.org/periodic-table/element/29/copper', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-sci-metals', 'Order these metals by melting point, lowest first.', 'rank', NULL, 'lower', NULL, '["f-tin-melt","f-gold-melt","f-iron-melt","f-tungsten-melt"]', '["f-tungsten-melt","f-tin-melt","f-iron-melt","f-gold-melt"]', 'At ordinary pressure, tin melts near 232 °C, gold near 1,064 °C, iron near 1,538 °C, and tungsten near 3,422 °C.', 'https://www.rsc.org/periodic-table/element/74/tungsten', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-sci-sound', 'How fast does sound travel in dry air at 20 °C?', 'estimate', 'm/s', 'higher', 'speed-ms', '["f-sound"]', '["f-sound"]', 'In dry air at 20 °C, sound travels at about 343 metres per second. The speed rises as the air gets warmer, so the temperature is part of the question.', 'https://en.wikipedia.org/wiki/Speed_of_sound', 'Wikipedia: Speed of sound', '2026-11-21', 'CC BY-SA 4.0', 'science', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-sci-atomic', 'Which element has the higher atomic number?', 'compare', NULL, 'higher', NULL, '["f-gold-z","f-lead-z"]', '["f-gold-z","f-lead-z"]', 'Gold is element 79. Lead is element 82. Atomic number is the proton count, and it is exact.', 'https://www.rsc.org/periodic-table/element/82/lead', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-cul-marathon', 'How long is a standard marathon?', 'estimate', 'km', 'higher', 'distance-km', '["f-marathon"]', '["f-marathon"]', 'World Athletics sets the marathon at 42.195 km, the distance standardized from the 1908 London course.', 'https://worldathletics.org/disciplines/road-running/marathon', 'World Athletics', '2026-11-21', 'World Athletics competition rules', 'culture', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-cul-premiere', 'Which book was published earlier?', 'compare', NULL, 'lower', NULL, '["f-principia","f-origin"]', '["f-origin","f-principia"]', 'Newton''s Principia was published in 1687. Darwin''s On the Origin of Species was published in 1859.', 'https://en.wikipedia.org/wiki/Philosophi%C3%A6_Naturalis_Principia_Mathematica', 'Wikipedia: Philosophiæ Naturalis Principia Mathematica', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-cul-works', 'Order these works by the year of their first performance, earliest first.', 'rank', NULL, 'lower', NULL, '["f-figaro","f-beethoven","f-rite","f-messiaen"]', '["f-rite","f-figaro","f-messiaen","f-beethoven"]', 'Figaro opened in 1786, Beethoven''s Ninth in 1824, The Rite of Spring in 1913, and Messiaen''s Quartet for the End of Time in a prisoner-of-war camp in 1941.', 'https://en.wikipedia.org/wiki/The_Marriage_of_Figaro', 'Wikipedia: The Marriage of Figaro', '2026-11-21', 'CC BY-SA 4.0', 'culture', 3, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-cul-paintings', 'Which painting has the larger surface area?', 'compare', NULL, 'higher', NULL, '["f-mona","f-guernica"]', '["f-mona","f-guernica"]', 'The Mona Lisa is 77 cm by 53 cm, under half a square metre. Guernica is 349.3 cm by 776.6 cm, about 27 square metres.', 'https://www.museoreinasofia.es/en/collections/artwork/guernica', 'Museo Reina Sofía', '2026-11-21', 'Museo Reina Sofía collection record', 'culture', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-cul-shakespeare', 'In what year was William Shakespeare born?', 'estimate', 'year', 'higher', 'years', '["f-shakespeare"]', '["f-shakespeare"]', 'Parish records show Shakespeare''s baptism on 26 April 1564. His birthday is traditionally marked on 23 April, but the birth date itself was not written down. The year was.', 'https://en.wikipedia.org/wiki/William_Shakespeare', 'Wikipedia: William Shakespeare', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-long-equator', 'What is the equatorial circumference of Earth?', 'estimate', 'km', 'higher', 'distance-km', '["f-equator"]', '["f-equator"]', 'NASA''s planetary fact sheet lists Earth''s equatorial circumference as 40,075 km. The polar circumference is a little shorter because Earth is not a perfect sphere.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-long-span', 'Which distance is longer?', 'compare', NULL, 'higher', NULL, '["f-moon-distance","f-sun-distance"]', '["f-moon-distance","f-sun-distance"]', 'The Moon''s average distance is 384,400 km. Earth''s average distance from the Sun is about 149.6 million km, roughly 400 times farther.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-long-rocky', 'Order these planets by equatorial diameter, smallest first.', 'rank', NULL, 'lower', NULL, '["f-mercury-diameter","f-mars-diameter","f-venus-diameter","f-earth-diameter"]', '["f-earth-diameter","f-mercury-diameter","f-venus-diameter","f-mars-diameter"]', 'Mercury is the smallest, then Mars, then Venus, then Earth. Venus is only slightly smaller than Earth. Diameters are the equatorial figures from NASA''s fact sheets.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-long-elements', 'How many chemical elements are on the periodic table?', 'estimate', 'elements', 'higher', 'count', '["f-elements"]', '["f-elements"]', 'IUPAC''s periodic table currently lists 118 confirmed elements. The last of the newest names were adopted in 2016.', 'https://iupac.org/what-we-do/periodic-table-of-elements/', 'IUPAC', '2026-11-21', 'IUPAC', 'science', 1, 0);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified) VALUES ('q-long-trenches', 'Which ocean trench is deeper?', 'compare', NULL, 'higher', NULL, '["f-challenger","f-puerto-rico"]', '["f-puerto-rico","f-challenger"]', 'Challenger Deep reaches about 10,935 m. The Puerto Rico Trench, the deepest part of the Atlantic, is about 8,400 m.', 'https://oceanexplorer.noaa.gov/ocean-fact/ocean-depth/', 'NOAA Ocean Exploration', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0);
INSERT INTO puzzles (slot, theme, blurb, question_ids) VALUES (0, 'Space', 'Distances, sizes, and how long a year really is.', '["q-space-moon","q-space-giants","q-space-orbits","q-space-light","q-space-year"]');
INSERT INTO puzzles (slot, theme, blurb, question_ids) VALUES (1, 'Planet Earth', 'Peaks, seas, and the deepest place in the ocean.', '["q-earth-everest","q-earth-seas","q-earth-oceans","q-earth-trench","q-earth-peaks"]');
INSERT INTO puzzles (slot, theme, blurb, question_ids) VALUES (2, 'The human body', 'Bones, cells, and the long road through the gut.', '["q-body-bones","q-body-lungs","q-body-counts","q-body-neurons","q-body-gut"]');
